const canonicalSearchTerms = new Set(searchAliasGroups.map(function(group) { return group[0]; }));

function canonicalizeSearch(value) {
  let normalized = String(value || "").toLocaleLowerCase().replace(/[০-৯]/g, function(digit) { return String("০১২৩৪৫৬৭৮৯".indexOf(digit)); });
  searchAliasGroups.forEach(function(group) {
    group[1].filter(function(alias) { return alias.includes(" "); }).sort(function(a, b) { return b.length - a.length; }).forEach(function(alias) {
      normalized = normalized.split(alias).join(" " + group[0] + " ");
    });
  });
  const aliases = new Map();
  searchAliasGroups.forEach(function(group) { group[1].filter(function(alias) { return !alias.includes(" "); }).forEach(function(alias) { aliases.set(alias, group[0]); }); });
  return (normalized.match(/[\p{L}\p{M}\p{N}+#.]+/gu) || []).map(function(token) { return aliases.get(token) || token; }).join(" ");
}

function escapeHtml(value) {
  return String(value == null ? "" : value).replace(/[&<>"']/g, function(char) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[char];
  });
}

function captureWorkspaceState() {
  return $$("input, textarea, select", $("#toolWorkspace")).map(function(element) {
    return { id: element.id, type: element.type, value: element.value, checked: element.checked, files: element.files ? Array.from(element.files) : [] };
  }).filter(function(item) { return item.id; });
}

function restoreWorkspaceState(items) {
  (items || []).forEach(function(item) {
    const element = $("#" + item.id);
    if (!element) return;
    if (item.type === "file" && item.files.length && typeof DataTransfer !== "undefined") {
      const transfer = new DataTransfer();
      item.files.forEach(function(file) { transfer.items.add(file); });
      element.files = transfer.files;
    } else if (item.type === "checkbox" || item.type === "radio") element.checked = item.checked;
    else element.value = item.value;
    element.dispatchEvent(new Event("input", { bubbles: true }));
    element.dispatchEvent(new Event("change", { bubbles: true }));
  });
}

