function metric(value, label) {
  return '<div class="metric"><strong>' + escapeHtml(value) + '</strong><span>' + escapeHtml(label) + '</span></div>';
}

function humanBytes(bytes) {
  if (!Number.isFinite(bytes) || bytes < 0) return "—";
  if (bytes < 1024) return displayNumber(bytes) + " B";
  if (bytes < 1048576) return displayNumber((bytes / 1024).toFixed(1)) + " KB";
  return displayNumber((bytes / 1048576).toFixed(2)) + " MB";
}

function ensureFileLimit(file, megabytes) {
  if (file && file.size > megabytes * 1048576) throw new Error(L("ফাইলটি খুব বড়—সর্বোচ্চ " + megabytes + " MB ব্যবহার করুন", "This file is too large—use a file up to " + megabytes + " MB"));
}

function ensureBatchLimit(files, megabytes) {
  const total = Array.from(files || []).reduce(function(sum, file) { return sum + file.size; }, 0);
  if (total > megabytes * 1048576) throw new Error(L("সব ফাইল মিলিয়ে সর্বোচ্চ " + megabytes + " MB ব্যবহার করুন", "Keep the combined files under " + megabytes + " MB"));
}

function ensureRasterImage(file) {
  const allowedTypes = new Set(["image/png", "image/jpeg", "image/webp", "image/gif", "image/bmp", "image/avif"]);
  const knownExtension = /\.(?:png|jpe?g|webp|gif|bmp|avif)$/i.test(file && file.name || "");
  if (!file || (!allowedTypes.has(file.type) && !(file.type === "" && knownExtension))) throw new Error(L("PNG, JPEG, WebP, GIF, BMP বা AVIF ছবি ব্যবহার করুন", "Use a PNG, JPEG, WebP, GIF, BMP or AVIF image"));
}

function copyText(textValue) {
  navigator.clipboard.writeText(String(textValue)).then(function() {
    showToast(L("কপি হয়েছে", "Copied"));
  }).catch(function() {
    showToast(L("কপি করা যায়নি", "Could not copy"));
  });
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(function() { URL.revokeObjectURL(url); }, 1500);
}

const scriptCache = {};
function loadScript(src, test) {
  if (test && test()) return Promise.resolve();
  if (scriptCache[src]) return scriptCache[src];
  scriptCache[src] = new Promise(function(resolve, reject) {
    const script = document.createElement("script");
    script.src = src;
    script.async = true;
    script.crossOrigin = "anonymous";
    script.referrerPolicy = "no-referrer";
    script.onload = function() { resolve(); };
    script.onerror = function() {
      delete scriptCache[src];
      script.remove();
      reject(new Error("Could not load required library"));
    };
    document.head.appendChild(script);
  });
  return scriptCache[src];
}

function calculateDateParts(birth, target) {
  const birthUtc = new Date(Date.UTC(birth.getFullYear(), birth.getMonth(), birth.getDate()));
  const targetUtc = new Date(Date.UTC(target.getFullYear(), target.getMonth(), target.getDate()));
  let totalMonths = (targetUtc.getUTCFullYear() - birthUtc.getUTCFullYear()) * 12 + targetUtc.getUTCMonth() - birthUtc.getUTCMonth();
  const monthAnchor = function(monthsFromBirth) {
    const rawMonth = birthUtc.getUTCMonth() + monthsFromBirth;
    const year = birthUtc.getUTCFullYear() + Math.floor(rawMonth / 12);
    const month = ((rawMonth % 12) + 12) % 12;
    const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
    return new Date(Date.UTC(year, month, Math.min(birthUtc.getUTCDate(), lastDay)));
  };
  if (monthAnchor(totalMonths) > targetUtc) totalMonths -= 1;
  const anchor = monthAnchor(totalMonths);
  const years = Math.floor(totalMonths / 12);
  const months = totalMonths % 12;
  const days = Math.round((targetUtc - anchor) / 86400000);
  return { years: years, months: months, days: days };
}

function bindAge() {
  const today = new Date();
  const todayString = today.getFullYear() + "-" + String(today.getMonth() + 1).padStart(2, "0") + "-" + String(today.getDate()).padStart(2, "0");
  $("#toolTarget").value = todayString;
  $("#toolTarget").max = todayString;
  $("#toolBirth").max = todayString;
  $("#runAge").addEventListener("click", function() {
    const birthValue = $("#toolBirth").value;
    const targetValue = $("#toolTarget").value;
    if (!birthValue || !targetValue) return showToast(t("invalidDate"));
    const birth = new Date(birthValue + "T12:00:00");
    const target = new Date(targetValue + "T12:00:00");
    if (birth > target) return showToast(t("futureDate"));
    const age = calculateDateParts(birth, target);
    const totalDays = Math.round((Date.UTC(target.getFullYear(), target.getMonth(), target.getDate()) - Date.UTC(birth.getFullYear(), birth.getMonth(), birth.getDate())) / 86400000);
    outputSet('<p class="workspace-kicker">' + L("নির্ভুল বয়স", "Precise age") + '</p><div class="metric-grid">' +
      metric(displayNumber(age.years), t("years")) + metric(displayNumber(age.months), t("months")) + metric(displayNumber(age.days), t("days")) +
      '</div><p class="result-copy" style="margin-top:18px">' + L("মোট প্রায় ", "Approximately ") + '<strong style="color:#fff">' + displayNumber(totalDays.toLocaleString("en-US")) + '</strong> ' + L("দিন", "days in total") + (state.lang === "bn" ? "।" : ".") + '</p>');
  });
}

function bindBmi() {
  $("#runBmi").addEventListener("click", function() {
    const height = Number($("#bmiHeight").value);
    const weight = Number($("#bmiWeight").value);
    if (!(height > 0 && weight > 0)) return showToast(L("সঠিক উচ্চতা ও ওজন দিন", "Enter valid height and weight"));
    const bmi = weight / Math.pow(height / 100, 2);
    let label;
    let note;
    if (bmi < 18.5) { label = L("কম ওজন", "Underweight"); note = L("স্বাস্থ্য পেশাজীবীর পরামর্শ বিবেচনা করুন।", "Consider speaking with a health professional."); }
    else if (bmi < 25) { label = L("স্বাভাবিক সীমা", "Typical range"); note = L("সাধারণ BMI নির্দেশিকা অনুযায়ী এই সীমা স্বাভাবিক।", "This falls in the typical adult BMI range."); }
    else if (bmi < 30) { label = L("অতিরিক্ত ওজন", "Overweight range"); note = L("একটি সাধারণ অনুমান—শরীরের গঠন এখানে ধরা হয় না।", "This is an estimate and does not account for body composition."); }
    else { label = L("উচ্চ BMI", "High BMI"); note = L("ব্যক্তিগত পরামর্শের জন্য স্বাস্থ্য পেশাজীবীর সাথে কথা বলুন।", "Talk with a health professional for personal guidance."); }
    outputSet('<p class="workspace-kicker">BMI</p><div class="big-result">' + displayNumber(bmi.toFixed(1)) + '</div><h3 class="result-title">' + label + '</h3><p class="result-copy">' + note + '</p>');
  });
}

function bindGpa() {
  $("#runGpa").addEventListener("click", function() {
    const rows = $$(".gpa-row");
    let weighted = 0;
    let credits = 0;
    rows.forEach(function(row) {
      const credit = Number($(".gpa-credit", row).value);
      const grade = Number($(".gpa-grade", row).value);
      if (credit > 0) {
        credits += credit;
        weighted += credit * grade;
      }
    });
    if (!credits) return showToast(L("কমপক্ষে একটি কোর্সের ক্রেডিট দিন", "Enter credits for at least one course"));
    const gpa = weighted / credits;
    outputSet('<p class="workspace-kicker">' + L("হিসাব করা ফল", "Calculated result") + '</p><div class="big-result">' + displayNumber(gpa.toFixed(2)) + '</div><div class="metric-grid">' + metric(displayNumber(credits), L("মোট ক্রেডিট", "Total credits")) + metric(displayNumber(weighted.toFixed(2)), L("গ্রেড পয়েন্ট", "Grade points")) + '</div>');
  });
}

function hexToRgb(hex) {
  const clean = String(hex).trim().replace("#", "");
  const full = clean.length === 3 ? clean.split("").map(function(c) { return c + c; }).join("") : clean;
  if (!/^[0-9a-f]{6}$/i.test(full)) return null;
  const number = parseInt(full, 16);
  return { r: number >> 16, g: (number >> 8) & 255, b: number & 255, hex: "#" + full.toUpperCase() };
}

function rgbToHsl(r, g, b) {
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  let h = 0;
  let s = 0;
  const l = (max + min) / 2;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    if (max === r) h = (g - b) / d + (g < b ? 6 : 0);
    if (max === g) h = (b - r) / d + 2;
    if (max === b) h = (r - g) / d + 4;
    h /= 6;
  }
  return { h: Math.round(h * 360), s: Math.round(s * 100), l: Math.round(l * 100) };
}

function bindColor() {
  const sync = function(value) {
    const rgb = hexToRgb(value);
    if (!rgb) return showToast(L("সঠিক HEX রঙ দিন", "Enter a valid HEX color"));
    $("#colorValue").value = rgb.hex;
    $("#colorPicker").value = rgb.hex.toLowerCase();
    const hsl = rgbToHsl(rgb.r, rgb.g, rgb.b);
    outputSet('<div class="color-swatch" style="background:' + rgb.hex + '"><span>' + rgb.hex + '</span></div><ul class="output-list"><li><span>HEX</span><strong>' + rgb.hex + '</strong></li><li><span>RGB</span><strong>rgb(' + rgb.r + ', ' + rgb.g + ', ' + rgb.b + ')</strong></li><li><span>HSL</span><strong>hsl(' + hsl.h + ', ' + hsl.s + '%, ' + hsl.l + '%)</strong></li></ul><button class="tool-button secondary" id="copyColor" type="button" style="margin-top:15px">' + L("সব কপি করুন", "Copy values") + '</button>');
    $("#copyColor").addEventListener("click", function() { copyText(rgb.hex + "\nrgb(" + rgb.r + ", " + rgb.g + ", " + rgb.b + ")\nhsl(" + hsl.h + ", " + hsl.s + "%, " + hsl.l + "%)"); });
  };
  $("#colorPicker").addEventListener("input", function(event) { $("#colorValue").value = event.target.value.toUpperCase(); sync(event.target.value); });
  $("#runColor").addEventListener("click", function() { sync($("#colorValue").value); });
  sync($("#colorValue").value);
}

function cryptoRandomIndex(size) {
  if (!(size > 0)) return 0;
  const range = 4294967296;
  const limit = Math.floor(range / size) * size;
  const sample = new Uint32Array(1);
  do { crypto.getRandomValues(sample); } while (sample[0] >= limit);
  return sample[0] % size;
}

function bindPassword() {
  const range = $("#passwordLength");
  range.addEventListener("input", function() { $("#passwordLengthValue").textContent = displayNumber(range.value); });
  $("#runPassword").addEventListener("click", function() {
    const sets = [];
    if ($("#passUpper").checked) sets.push("ABCDEFGHJKLMNPQRSTUVWXYZ");
    if ($("#passLower").checked) sets.push("abcdefghijkmnopqrstuvwxyz");
    if ($("#passNumber").checked) sets.push("23456789");
    if ($("#passSymbol").checked) sets.push("!@#$%^&*_-+=?");
    if (!sets.length) return showToast(L("অন্তত একটি অক্ষরের ধরন বেছে নিন", "Choose at least one character set"));
    const all = sets.join("");
    const length = Number(range.value);
    let value = "";
    sets.forEach(function(set) { value += set[cryptoRandomIndex(set.length)]; });
    for (let i = sets.length; i < length; i++) value += all[cryptoRandomIndex(all.length)];
    const characters = value.split("");
    for (let i = characters.length - 1; i > 0; i--) {
      const index = cryptoRandomIndex(i + 1);
      const current = characters[i];
      characters[i] = characters[index];
      characters[index] = current;
    }
    value = characters.join("");
    const bits = Math.round(length * Math.log2(all.length));
    outputSet('<p class="workspace-kicker">' + L("নিরাপদ পাসওয়ার্ড", "Secure password") + '</p><div class="code-output" style="min-height:auto;font-size:19px;overflow-wrap:anywhere">' + escapeHtml(value) + '</div><div class="metric-grid" style="margin-top:14px">' + metric(displayNumber(length), L("অক্ষর", "Characters")) + metric(displayNumber(bits), L("আনুমানিক বিট", "Estimated bits")) + '</div><button class="tool-button secondary" id="copyPassword" type="button" style="margin-top:15px">' + L("কপি করুন", "Copy password") + '</button>');
    $("#copyPassword").addEventListener("click", function() { copyText(value); });
  });
  $("#runPassword").click();
}

