function bindTyping() {
  const input = $("#typingInput");
  const promptText = $("#typingPrompt").textContent;
  let startedAt = 0;
  const update = function() {
    if (!startedAt && input.value) startedAt = Date.now();
    const elapsedMinutes = Math.max((Date.now() - startedAt) / 60000, 1 / 60);
    const typed = input.value;
    const words = (typed.trim().match(/\S+/g) || []).length;
    let correct = 0;
    for (let i = 0; i < typed.length; i++) if (typed[i] === promptText[i]) correct++;
    const accuracy = typed.length ? Math.round(correct / typed.length * 100) : 100;
    const wpm = typed.length ? Math.round(words / elapsedMinutes) : 0;
    outputSet('<p class="workspace-kicker">' + L("লাইভ ফল", "Live result") + '</p><div class="metric-grid">' + metric(displayNumber(wpm), "WPM") + metric(displayNumber(accuracy) + "%", L("নির্ভুলতা", "Accuracy")) + metric(displayNumber(words), L("শব্দ", "Words")) + '</div>');
  };
  input.addEventListener("input", update);
  $("#resetTyping").addEventListener("click", function() {
    input.value = "";
    startedAt = 0;
    outputSet(placeholder(L("টাইপিং ফল", "Typing result"), L("টাইপ শুরু করলে ফল দেখাবে।", "Start typing to see your result.")));
    input.focus();
  });
}

function keywordSet(textValue) {
  const stop = new Set(["the","and","for","with","you","your","this","that","from","are","was","have","has","will","our","but","not","all","can","একটি","এবং","জন্য","থেকে","করে","হবে","সাথে","এই"]);
  const words = (textValue.toLowerCase().match(/[a-z0-9+#.]{3,}|[\u0980-\u09ff]{3,}/g) || []);
  return new Set(words.filter(function(word) { return !stop.has(word); }));
}

