function bindQrTool(toolItem) {
  $("#runQr").addEventListener("click", async function() {
    const button = $("#runQr");
    button.disabled = true;
    try {
      if (toolItem.key === "qr-maker") {
        const value = $("#qrText").value.trim();
        if (!value) throw new Error(L("লিংক বা লেখা দিন", "Enter a link or text"));
        await loadScript("./vendor/qrcode.min.js", function() { return !!window.QRCode; });
        const size = Number($("#qrSize").value);
        outputSet('<p class="workspace-kicker">' + L("QR কোড প্রস্তুত", "QR code ready") + '</p><div id="qrMount" style="display:grid;place-items:center;padding:18px;background:#fff;border-radius:10px;width:max-content;max-width:100%"></div><button class="tool-button secondary" id="downloadQr" type="button" style="margin-top:15px">' + L("PNG ডাউনলোড", "Download PNG") + '</button>');
        new QRCode($("#qrMount"), { text: value, width: size, height: size, colorDark: $("#qrColor").value, colorLight: "#ffffff", correctLevel: QRCode.CorrectLevel.H });
        setTimeout(function() {
          $("#downloadQr").addEventListener("click", function() {
            const canvas = $("#qrMount canvas");
            const image = $("#qrMount img");
            if (canvas) canvas.toBlob(function(blob) { downloadBlob(blob, "toolbari-qr.png"); });
            else if (image) {
              const link = document.createElement("a");
              link.href = image.src; link.download = "toolbari-qr.png"; link.click();
            }
          });
        }, 50);
      } else {
        const file = $("#qrFile").files[0];
        if (!file) throw new Error(L("QR কোডের ছবি বেছে নিন", "Choose a QR code image"));
        ensureFileLimit(file, 10);
        const image = await readImage(file);
        if (image.naturalWidth * image.naturalHeight > 25000000) throw new Error(L("QR ছবির রেজোলিউশন খুব বড়—২৫ মেগাপিক্সেলের নিচে ব্যবহার করুন", "The QR image is too large—use one under 25 megapixels"));
        let result = "";
        if ("BarcodeDetector" in window) {
          const detector = new BarcodeDetector({ formats: ["qr_code"] });
          const found = await detector.detect(image);
          result = found[0] ? found[0].rawValue : "";
        }
        if (!result) {
          await loadScript("./vendor/jsQR.js", function() { return !!window.jsQR; });
          const canvas = createCanvas(image.width, image.height);
          const ctx = canvas.getContext("2d", { willReadFrequently: true });
          ctx.drawImage(image, 0, 0);
          const pixels = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(pixels.data, pixels.width, pixels.height);
          result = code ? code.data : "";
        }
        if (!result) throw new Error(L("কোনো QR কোড পাওয়া যায়নি", "No QR code was detected"));
        outputSet('<p class="workspace-kicker">' + L("স্ক্যান ফল", "Scan result") + '</p><div class="code-output" style="min-height:90px">' + escapeHtml(result) + '</div><button class="tool-button secondary" id="copyQrResult" type="button" style="margin-top:15px">' + L("কপি করুন", "Copy result") + '</button>');
        $("#copyQrResult").addEventListener("click", function() { copyText(result); });
      }
    } catch (error) {
      outputSet('<h3 class="result-title">' + L("QR কাজটি সম্পন্ন হয়নি", "QR task did not complete") + '</h3><p class="result-copy">' + escapeHtml(error.message || String(error)) + '</p>');
    } finally {
      button.disabled = false;
    }
  });
}

function getYoutubeId(value) {
  const clean = String(value).trim();
  const validId = function(candidate) { return /^[a-zA-Z0-9_-]{11}$/.test(candidate || "") ? candidate : ""; };
  if (/^[a-zA-Z0-9_-]{11}$/.test(clean)) return clean;
  try {
    const url = new URL(clean);
    const hostname = url.hostname.toLowerCase().replace(/^www\./, "");
    const isShort = hostname === "youtu.be";
    const isYoutube = hostname === "youtube.com" || hostname.endsWith(".youtube.com") || hostname === "youtube-nocookie.com" || hostname.endsWith(".youtube-nocookie.com");
    if (!isShort && !isYoutube) return "";
    if (isShort) return validId(url.pathname.split("/").filter(Boolean)[0] || "");
    if (url.searchParams.get("v")) return validId(url.searchParams.get("v"));
    const parts = url.pathname.split("/").filter(Boolean);
    const marker = parts.findIndex(function(part) { return ["embed","shorts","live"].includes(part); });
    return marker >= 0 ? validId(parts[marker + 1] || "") : "";
  } catch { return ""; }
}

