function bindWordPdf() {
  $("#wordFile").addEventListener("change", async function() {
    const file = this.files[0];
    if (!file) return;
    try {
      ensureFileLimit(file, 10);
      if (!/\.docx$/i.test(file.name)) throw new Error(L("শুধু .docx ফাইল ব্যবহার করুন", "Choose a .docx file"));
      await loadScript("./vendor/jszip.min.js", function() { return !!window.JSZip; });
      const zip = await JSZip.loadAsync(await file.arrayBuffer());
      const documentPart = zip.file("word/document.xml");
      if (!documentPart) throw new Error(L("এই DOCX-এ লেখা পাওয়া যায়নি", "No document text was found in this DOCX"));
      const xmlText = await documentPart.async("string");
      if (xmlText.length > 2000000) throw new Error(L("ডকুমেন্টটি এই ব্রাউজার টুলের জন্য খুব বড়", "This document is too large for the browser tool"));
      const xml = new DOMParser().parseFromString(xmlText, "application/xml");
      if (xml.getElementsByTagName("parsererror").length) throw new Error(L("DOCX-এর লেখা পড়া যায়নি", "Could not read DOCX text"));
      const namespace = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
      const paragraphs = Array.from(xml.getElementsByTagNameNS(namespace, "p"));
      const content = paragraphs.map(function(paragraph) {
        return Array.from(paragraph.getElementsByTagNameNS(namespace, "t")).map(function(node) { return node.textContent; }).join("");
      }).join("\n");
      if (!content.trim()) throw new Error(L("DOCX-এ সাধারণ লেখা পাওয়া যায়নি", "No basic text was found in the DOCX"));
      $("#wordContent").value = content;
      if (!$("#wordTitle").value.trim()) $("#wordTitle").value = file.name.replace(/\.docx$/i, "");
      update();
    } catch (error) {
      outputSet('<h3 class="result-title">' + L("DOCX পড়া যায়নি", "Could not read DOCX") + '</h3><p class="result-copy">' + escapeHtml(error.message || String(error)) + '</p>');
    }
  });
  const update = function() {
    const title = $("#wordTitle").value.trim() || L("শিরোনামহীন ডকুমেন্ট", "Untitled document");
    const content = $("#wordContent").value;
    outputSet('<p class="workspace-kicker">' + L("প্রিন্ট প্রিভিউ", "Print preview") + '</p><h3 class="result-title">' + escapeHtml(title) + '</h3><div class="code-output" style="font-family:Arial,sans-serif">' + escapeHtml(content || L("লেখা এখানে দেখাবে…", "Your text appears here…")) + '</div><button class="tool-button secondary" id="printWord" type="button" style="margin-top:15px">' + L("প্রিন্ট / PDF", "Print / PDF") + '</button>');
    $("#printWord").addEventListener("click", function() { printableWindow(title, '<h1>' + escapeHtml(title) + '</h1><pre>' + escapeHtml(content) + '</pre>'); });
  };
  $("#runWordPdf").addEventListener("click", update);
  $("#wordTitle").addEventListener("input", update);
  $("#wordContent").addEventListener("input", update);
}

