function expansionNumber(value, maximumFractionDigits) {
  return new Intl.NumberFormat(state.lang === "bn" ? "bn-BD" : "en-US", {
    maximumFractionDigits: maximumFractionDigits == null ? 6 : maximumFractionDigits
  }).format(value);
}

function normalizeNumerals(value) {
  return String(value == null ? "" : value).replace(/[০-৯]/g, function(digit) { return String("০১২৩৪৫৬৭৮৯".indexOf(digit)); });
}

function finiteInput(id, message) {
  const raw = normalizeNumerals($("#" + id).value).trim();
  if (!raw) throw new Error(message || L("সঠিক সংখ্যা দিন", "Enter a valid number"));
  const value = Number(raw);
  if (!Number.isFinite(value)) throw new Error(message || L("সঠিক সংখ্যা দিন", "Enter a valid number"));
  return value;
}

function utcDateFromIso(value) {
  const match = String(value).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) throw new Error(L("সঠিক তারিখ দিন", "Choose a valid date"));
  const year = Number(match[1]);
  const month = Number(match[2]) - 1;
  const day = Number(match[3]);
  const date = new Date(0);
  date.setUTCHours(0, 0, 0, 0);
  date.setUTCFullYear(year, month, day);
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month || date.getUTCDate() !== day) throw new Error(L("সঠিক তারিখ দিন", "Choose a valid date"));
  return date.getTime();
}

function showExpansionError(error) {
  outputSet('<h3 class="result-title">' + L("কাজটি সম্পন্ন হয়নি", "Could not complete the task") + '</h3><p class="result-copy">' + escapeHtml(error && error.message ? error.message : String(error)) + '</p>');
}

function bindSafeClick(id, handler) {
  const button = $("#" + id);
  if (!button) return;
  button.addEventListener("click", async function() {
    button.disabled = true;
    try { await handler(button); }
    catch (error) { showExpansionError(error); }
    finally { button.disabled = false; }
  });
}

function showCopyableResult(title, value, filename, note) {
  const fullValue = String(value);
  const truncated = fullValue.length > 20000;
  const preview = truncated ? fullValue.slice(0, 20000) + "\n…" : fullValue;
  const notes = [note, truncated ? L("প্রিভিউতে প্রথম ২০,০০০ অক্ষর দেখানো হয়েছে; কপি ও ডাউনলোডে সম্পূর্ণ ফল থাকবে।", "The preview shows the first 20,000 characters; copy and download keep the complete result.") : ""].filter(Boolean).join(" ");
  outputSet('<p class="workspace-kicker">' + escapeHtml(title) + '</p><pre class="code-output" id="expansionTextOutput">' + escapeHtml(preview) + '</pre><div class="action-row" style="margin-top:14px"><button class="tool-button secondary" id="copyExpansionOutput" type="button">' + L("কপি করুন", "Copy") + '</button>' + (filename ? '<button class="tool-button secondary" id="downloadExpansionOutput" type="button">' + L("ফাইল ডাউনলোড", "Download file") + '</button>' : "") + '</div>' + (notes ? '<p class="micro-note" style="color:#a9bbb6;margin-top:12px">' + escapeHtml(notes) + '</p>' : ""));
  $("#copyExpansionOutput").addEventListener("click", function() { copyText(fullValue); });
  if (filename) $("#downloadExpansionOutput").addEventListener("click", function() {
    const lowerName = filename.toLocaleLowerCase();
    const isCsv = lowerName.endsWith(".csv");
    const mime = isCsv ? "text/csv;charset=utf-8" : (lowerName.endsWith(".json") ? "application/json;charset=utf-8" : "text/plain;charset=utf-8");
    downloadBlob(new Blob([isCsv ? "\uFEFF" + fullValue : fullValue], { type: mime }), filename);
  });
}

function unitDefinitions() {
  return {
    length: [["m", L("মিটার", "Metre"), 1], ["km", L("কিলোমিটার", "Kilometre"), 1000], ["cm", L("সেন্টিমিটার", "Centimetre"), 0.01], ["mm", L("মিলিমিটার", "Millimetre"), 0.001], ["ft", L("ফুট", "Foot"), 0.3048], ["in", L("ইঞ্চি", "Inch"), 0.0254], ["mi", L("মাইল", "Mile"), 1609.344]],
    weight: [["kg", L("কিলোগ্রাম", "Kilogram"), 1], ["g", L("গ্রাম", "Gram"), 0.001], ["mg", L("মিলিগ্রাম", "Milligram"), 0.000001], ["lb", L("পাউন্ড", "Pound"), 0.45359237], ["oz", L("আউন্স", "Ounce"), 0.028349523125]],
    temperature: [["c", "Celsius (°C)"], ["f", "Fahrenheit (°F)"], ["k", "Kelvin (K)"]],
    area: [["sqm", L("বর্গমিটার", "Square metre"), 1], ["sqft", L("বর্গফুট", "Square foot"), 0.09290304], ["sqkm", L("বর্গকিলোমিটার", "Square kilometre"), 1000000], ["acre", L("একর", "Acre"), 4046.8564224], ["hectare", L("হেক্টর", "Hectare"), 10000]],
    volume: [["l", L("লিটার", "Litre"), 1], ["ml", L("মিলিলিটার", "Millilitre"), 0.001], ["m3", L("ঘনমিটার", "Cubic metre"), 1000], ["gal", L("US গ্যালন", "US gallon"), 3.785411784], ["cup", L("US কাপ", "US cup"), 0.2365882365]],
    data: [["b", "Byte", 1], ["kb", "KB", 1000], ["mb", "MB", 1000000], ["gb", "GB", 1000000000], ["kib", "KiB", 1024], ["mib", "MiB", 1048576], ["gib", "GiB", 1073741824]]
  };
}

function convertTemperature(value, from, to) {
  let celsius = value;
  if (from === "f") celsius = (value - 32) * 5 / 9;
  else if (from === "k") celsius = value - 273.15;
  if (to === "f") return celsius * 9 / 5 + 32;
  if (to === "k") return celsius + 273.15;
  return celsius;
}

const banglaUnderHundred = ["শূন্য","এক","দুই","তিন","চার","পাঁচ","ছয়","সাত","আট","নয়","দশ","এগারো","বারো","তেরো","চৌদ্দ","পনেরো","ষোলো","সতেরো","আঠারো","উনিশ","বিশ","একুশ","বাইশ","তেইশ","চব্বিশ","পঁচিশ","ছাব্বিশ","সাতাশ","আটাশ","ঊনত্রিশ","ত্রিশ","একত্রিশ","বত্রিশ","তেত্রিশ","চৌত্রিশ","পঁয়ত্রিশ","ছত্রিশ","সাঁইত্রিশ","আটত্রিশ","ঊনচল্লিশ","চল্লিশ","একচল্লিশ","বিয়াল্লিশ","তেতাল্লিশ","চুয়াল্লিশ","পঁয়তাল্লিশ","ছেচল্লিশ","সাতচল্লিশ","আটচল্লিশ","ঊনপঞ্চাশ","পঞ্চাশ","একান্ন","বাহান্ন","তিপ্পান্ন","চুয়ান্ন","পঞ্চান্ন","ছাপ্পান্ন","সাতান্ন","আটান্ন","ঊনষাট","ষাট","একষট্টি","বাষট্টি","তেষট্টি","চৌষট্টি","পঁয়ষট্টি","ছেষট্টি","সাতষট্টি","আটষট্টি","ঊনসত্তর","সত্তর","একাত্তর","বাহাত্তর","তিয়াত্তর","চুয়াত্তর","পঁচাত্তর","ছিয়াত্তর","সাতাত্তর","আটাত্তর","ঊনআশি","আশি","একাশি","বিরাশি","তিরাশি","চুরাশি","পঁচাশি","ছিয়াশি","সাতাশি","আটাশি","ঊননব্বই","নব্বই","একানব্বই","বিরানব্বই","তিরানব্বই","চুরানব্বই","পঁচানব্বই","ছিয়ানব্বই","সাতানব্বই","আটানব্বই","নিরানব্বই"];
const englishSmall = ["zero","one","two","three","four","five","six","seven","eight","nine","ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"];
const englishTens = ["","","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"];

function wordsBelowThousand(value, lang) {
  const number = Math.floor(value);
  if (lang === "bn") {
    if (number < 100) return banglaUnderHundred[number];
    const rest = number % 100;
    return banglaUnderHundred[Math.floor(number / 100)] + " শত" + (rest ? " " + banglaUnderHundred[rest] : "");
  }
  if (number < 20) return englishSmall[number];
  if (number < 100) return englishTens[Math.floor(number / 10)] + (number % 10 ? "-" + englishSmall[number % 10] : "");
  const rest = number % 100;
  return englishSmall[Math.floor(number / 100)] + " hundred" + (rest ? " " + wordsBelowThousand(rest, lang) : "");
}

function indianNumberWords(value, lang) {
  const number = Math.floor(value);
  if (number === 0) return lang === "bn" ? banglaUnderHundred[0] : englishSmall[0];
  const units = lang === "bn" ? [[10000000,"কোটি"],[100000,"লাখ"],[1000,"হাজার"]] : [[10000000,"crore"],[100000,"lakh"],[1000,"thousand"]];
  let remainder = number;
  const parts = [];
  units.forEach(function(unit) {
    if (remainder >= unit[0]) {
      const count = Math.floor(remainder / unit[0]);
      parts.push((count >= 1000 ? indianNumberWords(count, lang) : wordsBelowThousand(count, lang)) + " " + unit[1]);
      remainder %= unit[0];
    }
  });
  if (remainder) parts.push(wordsBelowThousand(remainder, lang));
  return parts.join(" ");
}

function utf8ToBase64(value) {
  const bytes = new TextEncoder().encode(value);
  let binary = "";
  for (let offset = 0; offset < bytes.length; offset += 32768) binary += String.fromCharCode.apply(null, bytes.subarray(offset, offset + 32768));
  return btoa(binary);
}

function base64ToUtf8(value) {
  const compact = String(value).replace(/\s+/g, "");
  const binary = atob(compact);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
}

function bytesToHex(buffer) {
  return Array.from(new Uint8Array(buffer)).map(function(byte) { return byte.toString(16).padStart(2, "0"); }).join("");
}

function escapeCsvCell(value) {
  let textValue = value == null ? "" : (typeof value === "object" ? JSON.stringify(value) : String(value));
  if (/^[=+\-@\t\r]/.test(textValue)) textValue = "'" + textValue;
  return /[",\r\n]/.test(textValue) ? '"' + textValue.replace(/"/g, '""') + '"' : textValue;
}

function jsonToCsv(records) {
  if (!Array.isArray(records)) records = [records];
  if (!records.length) return "";
  if (records.some(function(row) { return row == null || Array.isArray(row) || typeof row !== "object"; })) throw new Error(L("JSON-এ object-এর array দিন", "Use a JSON array of objects"));
  const headers = [];
  records.forEach(function(row) { Object.keys(row).forEach(function(key) { if (!headers.includes(key)) headers.push(key); }); });
  return [headers.map(escapeCsvCell).join(",")].concat(records.map(function(row) { return headers.map(function(key) { return escapeCsvCell(row[key]); }).join(","); })).join("\n");
}

function secureUuid() {
  if (crypto.randomUUID) return crypto.randomUUID();
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  bytes[6] = (bytes[6] & 15) | 64;
  bytes[8] = (bytes[8] & 63) | 128;
  const hex = Array.from(bytes).map(function(value) { return value.toString(16).padStart(2, "0"); }).join("");
  return hex.slice(0,8) + "-" + hex.slice(8,12) + "-" + hex.slice(12,16) + "-" + hex.slice(16,20) + "-" + hex.slice(20);
}

function assertSafeJsonNumbers(textValue) {
  let inString = false;
  let escaped = false;
  for (let i = 0; i < textValue.length; i++) {
    const char = textValue[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === '"') inString = false;
      continue;
    }
    if (char === '"') { inString = true; continue; }
    if (char !== "-" && (char < "0" || char > "9")) continue;
    const match = textValue.slice(i).match(/^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?/);
    if (!match) continue;
    const token = match[0];
    const numeric = Number(token);
    const isIntegerToken = !/[.eE]/.test(token);
    let unsafe = !Number.isFinite(numeric);
    const mantissaToken = token.split(/[eE]/)[0];
    if (!unsafe && numeric === 0 && /[1-9]/.test(mantissaToken)) unsafe = true;
    if (!unsafe && isIntegerToken) {
      try { unsafe = BigInt(token) > BigInt(Number.MAX_SAFE_INTEGER) || BigInt(token) < BigInt(Number.MIN_SAFE_INTEGER); }
      catch { unsafe = true; }
    } else if (!unsafe) {
      const mantissa = token.split(/[eE]/)[0].replace(/^[+-]/, "").replace(".", "").replace(/^0+/, "");
      if (mantissa.length > 15) unsafe = true;
    }
    if (unsafe) throw new Error(L("JSON সংখ্যাটি browser-এর নিরাপদ precision-এর বাইরে—মানটি উদ্ধৃত string হিসেবে দিন", "A JSON number exceeds safe browser precision—provide it as a quoted string"));
    i += token.length - 1;
  }
}

function parseJsonSafely(textValue) {
  assertSafeJsonNumbers(textValue);
  try { return JSON.parse(textValue); }
  catch { throw new Error(L("JSON-এর গঠন সঠিক নয়", "JSON syntax is invalid")); }
}

function decodeJwtPart(value) {
  try {
    const normalized = value.replace(/-/g, "+").replace(/_/g, "/").padEnd(Math.ceil(value.length / 4) * 4, "=");
    return parseJsonSafely(base64ToUtf8(normalized));
  } catch (error) {
    if (error && /precision/.test(error.message)) throw error;
    throw new Error(L("JWT-এর encoded JSON পড়া যায়নি", "The JWT's encoded JSON could not be read"));
  }
}

function bindExpansionTool(toolItem) {
  if (toolItem.key === "unit-converter") {
    const updateUnits = function() {
      const definitions = unitDefinitions()[$("#unitType").value];
      const options = definitions.map(function(unit) { return '<option value="' + unit[0] + '">' + escapeHtml(unit[1]) + '</option>'; }).join("");
      $("#unitFrom").innerHTML = options;
      $("#unitTo").innerHTML = options;
      if (definitions.length > 1) $("#unitTo").selectedIndex = 1;
    };
    $("#unitType").addEventListener("change", updateUnits);
    updateUnits();
    return bindSafeClick("runUnit", function() {
      const value = finiteInput("unitValue");
      const type = $("#unitType").value;
      const from = $("#unitFrom").value;
      const to = $("#unitTo").value;
      const definitions = unitDefinitions()[type];
      let result;
      if (type === "temperature") {
        if (convertTemperature(value, from, "c") < -273.1500001) throw new Error(L("তাপমাত্রা absolute zero-এর নিচে হতে পারে না", "Temperature cannot be below absolute zero"));
        result = convertTemperature(value, from, to);
      }
      else {
        const fromUnit = definitions.find(function(unit) { return unit[0] === from; });
        const toUnit = definitions.find(function(unit) { return unit[0] === to; });
        result = value * fromUnit[2] / toUnit[2];
      }
      const fromLabel = definitions.find(function(unit) { return unit[0] === from; })[1];
      const toLabel = definitions.find(function(unit) { return unit[0] === to; })[1];
      if (!Number.isFinite(result)) throw new Error(L("ফলটি নিরাপদ সংখ্যার সীমার বাইরে", "The result is outside the supported numeric range"));
      outputSet('<p class="workspace-kicker">' + L("রূপান্তর ফল", "Converted value") + '</p><div class="big-result">' + escapeHtml(expansionNumber(result, 10)) + '</div><p class="result-copy">' + escapeHtml(expansionNumber(value, 10) + " " + fromLabel + " = " + expansionNumber(result, 10) + " " + toLabel) + '</p>');
    });
  }
  if (toolItem.key === "land-converter") return bindSafeClick("runLand", function() {
    const value = finiteInput("landValue");
    if (value < 0) throw new Error(L("ঋণাত্মক জমির পরিমাণ দেওয়া যাবে না", "Land amount cannot be negative"));
    const factors = { decimal: 435.6, katha: 720, bigha: 14400, acre: 43560, sqft: 1, sqm: 10.7639104167 };
    const baseSqft = value * factors[$("#landFrom").value];
    const result = baseSqft / factors[$("#landTo").value];
    if (!Number.isFinite(baseSqft) || !Number.isFinite(result)) throw new Error(L("ফলটি নিরাপদ সংখ্যার সীমার বাইরে", "The result is outside the supported numeric range"));
    const toLabel = $("#landTo").selectedOptions[0].textContent;
    outputSet('<p class="workspace-kicker">' + L("জমির মাপ", "Land conversion") + '</p><div class="big-result">' + escapeHtml(expansionNumber(result, 8)) + '</div><p class="result-copy">' + escapeHtml(toLabel) + '</p>' + '<ul class="output-list"><li><span>' + L("বর্গফুটে", "In square feet") + '</span><strong>' + escapeHtml(expansionNumber(baseSqft, 4)) + '</strong></li><li><span>' + L("শতক/ডেসিমেলে", "In decimal/shotok") + '</span><strong>' + escapeHtml(expansionNumber(baseSqft / factors.decimal, 6)) + '</strong></li></ul>');
  });
  if (toolItem.key === "percentage") return bindSafeClick("runPercentage", function() {
    const base = finiteInput("percentBase");
    const rate = finiteInput("percentRate");
    const discount = finiteInput("discountRate");
    const vat = finiteInput("vatRate");
    if (discount < 0 || discount > 100 || vat < 0) throw new Error(L("ছাড় ০–১০০% এবং VAT ০ বা তার বেশি দিন", "Use a 0–100% discount and a non-negative VAT rate"));
    const percentValue = base * rate / 100;
    const afterDiscount = base * (1 - discount / 100);
    const finalPrice = afterDiscount * (1 + vat / 100);
    if (![percentValue, afterDiscount, finalPrice].every(Number.isFinite)) throw new Error(L("ফলটি নিরাপদ সংখ্যার সীমার বাইরে", "The result is outside the supported numeric range"));
    outputSet('<p class="workspace-kicker">' + L("হিসাব", "Calculation") + '</p><div class="metric-grid">' + metric(expansionNumber(percentValue, 4), rate + "% " + L("এর মান", "of base")) + metric(expansionNumber(afterDiscount, 4), L("ছাড়ের পর", "After discount")) + metric(expansionNumber(finalPrice, 4), L("VAT-সহ মোট", "Total with VAT")) + '</div>');
  });
  if (toolItem.key === "loan-emi") return bindSafeClick("runLoan", function() {
    const principal = finiteInput("loanPrincipal");
    const annualRate = finiteInput("loanRate");
    const months = finiteInput("loanMonths");
    if (principal <= 0 || annualRate < 0 || !Number.isInteger(months) || months < 1 || months > 600) throw new Error(L("সঠিক ঋণ, সুদ ও পূর্ণ ১–৬০০ মাস মেয়াদ দিন", "Enter a valid loan, rate and a whole-month term from 1–600"));
    const monthlyRate = annualRate / 1200;
    const payment = monthlyRate === 0 ? principal / months : principal * monthlyRate * Math.pow(1 + monthlyRate, months) / (Math.pow(1 + monthlyRate, months) - 1);
    const total = payment * months;
    if (!Number.isFinite(payment) || !Number.isFinite(total)) throw new Error(L("এই মানগুলোর EMI হিসাব করা যায়নি", "The EMI could not be calculated for these values"));
    outputSet('<p class="workspace-kicker">' + L("মাসিক কিস্তি", "Monthly payment") + '</p><div class="big-result">৳' + escapeHtml(expansionNumber(payment, 2)) + '</div><div class="metric-grid">' + metric("৳" + expansionNumber(total, 2), L("মোট পরিশোধ", "Total repayment")) + metric("৳" + expansionNumber(total - principal, 2), L("মোট সুদ", "Total interest")) + metric(expansionNumber(months, 0), L("মাস", "Months")) + '</div>');
  });
  if (toolItem.key === "date-business") return bindSafeClick("runBusinessDate", function() {
    const startMs = utcDateFromIso($("#businessStart").value);
    const endMs = utcDateFromIso($("#businessEnd").value);
    if (endMs < startMs) throw new Error(L("শেষ তারিখ শুরুর তারিখের পরে হতে হবে", "The end date must not be before the start date"));
    const between = Math.round((endMs - startMs) / 86400000);
    const inclusive = between + 1;
    let weekdays = Math.floor(inclusive / 7) * 5;
    const remainder = inclusive % 7;
    const startDay = new Date(startMs).getUTCDay();
    for (let i = 0; i < remainder; i++) { const day = (startDay + i) % 7; if (day !== 5 && day !== 6) weekdays++; }
    outputSet('<p class="workspace-kicker">' + L("তারিখের ব্যবধান", "Date difference") + '</p><div class="metric-grid">' + metric(expansionNumber(between, 0), L("দিনের ব্যবধান", "Days between")) + metric(expansionNumber(weekdays, 0), L("কর্মদিবস (দুই তারিখসহ)", "Business days (inclusive)")) + metric(expansionNumber(inclusive - weekdays, 0), L("সপ্তাহান্ত (দুই তারিখসহ)", "Weekend days (inclusive)")) + '</div>');
  });
  if (toolItem.key === "taka-words") return bindSafeClick("runTakaWords", function() {
    const amount = finiteInput("takaAmount");
    if (amount < 0 || amount > 999999999999.99) throw new Error(L("০ থেকে ৯৯৯,৯৯৯,৯৯৯,৯৯৯.৯৯-এর মধ্যে পরিমাণ দিন", "Enter an amount from 0 to 999,999,999,999.99"));
    const totalPoisha = Math.round((amount + Number.EPSILON) * 100);
    const taka = Math.floor(totalPoisha / 100);
    const poisha = totalPoisha % 100;
    const bn = indianNumberWords(taka, "bn") + " টাকা" + (poisha ? " " + indianNumberWords(poisha, "bn") + " পয়সা" : "") + " মাত্র";
    const en = indianNumberWords(taka, "en") + " taka" + (poisha ? " and " + indianNumberWords(poisha, "en") + " poisha" : "") + " only";
    outputSet('<p class="workspace-kicker">' + L("বাংলা ও English", "Bangla and English") + '</p><h3 class="result-title">' + escapeHtml(bn) + '</h3><p class="result-copy" style="font-size:16px">' + escapeHtml(en.replace(/\b\w/g, function(letter) { return letter.toUpperCase(); })) + '</p><button class="tool-button secondary" id="copyTakaWords" type="button">' + L("দুইটি লাইন কপি করুন", "Copy both lines") + '</button>');
    $("#copyTakaWords").addEventListener("click", function() { copyText(bn + "\n" + en); });
  });
  if (toolItem.key === "case-converter") return bindSafeClick("runCase", function() {
    const input = $("#caseInput").value;
    const mode = $("#caseMode").value;
    let result = input;
    if (mode === "upper") result = input.toLocaleUpperCase();
    else if (mode === "lower") result = input.toLocaleLowerCase();
    else if (mode === "title") result = input.toLocaleLowerCase().replace(/\p{L}[\p{L}\p{M}'’]*/gu, function(word) { return word.charAt(0).toLocaleUpperCase() + word.slice(1); });
    else result = input.toLocaleLowerCase().replace(/(^|[.!?।]\s*)([\p{L}])/gu, function(match, prefix, letter) { return prefix + letter.toLocaleUpperCase(); });
    showCopyableResult(L("রূপান্তরিত লেখা", "Converted text"), result, "toolbari-case.txt");
  });
  if (toolItem.key === "text-cleaner") return bindSafeClick("runCleaner", function() {
    let lines = $("#cleanerInput").value.replace(/\r\n?/g, "\n").split("\n");
    if ($("#cleanSpaces").checked) lines = lines.map(function(line) { return line.trim().replace(/[ \t]+/g, " "); });
    if ($("#cleanBlank").checked) lines = lines.filter(function(line) { return line.trim(); });
    if ($("#cleanDuplicate").checked) { const seen = new Set(); lines = lines.filter(function(line) { const key = line.trim(); if (seen.has(key)) return false; seen.add(key); return true; }); }
    if ($("#cleanSort").checked) lines.sort(function(a, b) { return a.localeCompare(b, state.lang === "bn" ? "bn" : "en", { numeric: true, sensitivity: "base" }); });
    const result = lines.join("\n");
    showCopyableResult(L("পরিষ্কার লেখা", "Cleaned text"), result, "toolbari-cleaned.txt", L("মূল " + $("#cleanerInput").value.length + " অক্ষর → " + result.length + " অক্ষর", "Original " + $("#cleanerInput").value.length + " characters → " + result.length + " characters"));
  });
  if (toolItem.key === "json-formatter") return bindSafeClick("runJson", function() {
    const input = $("#jsonInput").value;
    if (!input.trim()) throw new Error(L("JSON দিন", "Enter JSON"));
    const parsed = parseJsonSafely(input);
    const result = JSON.stringify(parsed, null, $("#jsonMode").value === "pretty" ? 2 : 0);
    showCopyableResult(L("বৈধ JSON", "Valid JSON"), result, "toolbari-data.json", L("JSON বৈধ এবং নিরাপদভাবে parse হয়েছে।", "The JSON parsed successfully."));
  });
  if (toolItem.key === "csv-json") return bindSafeClick("runDataCodec", function() {
    const input = $("#dataCodecInput").value;
    if (!input.trim()) throw new Error(L("ডেটা দিন", "Enter data"));
    let result;
    let filename;
    if ($("#dataCodecMode").value === "csv-json") {
      const rows = csvToRows(input);
      if (!rows.length || !rows[0].length) throw new Error(L("CSV header পাওয়া যায়নি", "CSV headers were not found"));
      const headerCounts = new Map();
      const maximumColumns = rows.reduce(function(maximum, row) { return Math.max(maximum, row.length); }, 0);
      const rawHeaders = Array.from({ length: maximumColumns }, function(unused, index) { return rows[0][index] == null ? "" : rows[0][index]; });
      const headers = rawHeaders.map(function(header, index) {
        const base = header.trim() || "column_" + (index + 1);
        const count = (headerCounts.get(base) || 0) + 1;
        headerCounts.set(base, count);
        return count === 1 ? base : base + "_" + count;
      });
      const objects = rows.slice(1).filter(function(row) { return row.some(function(cell) { return cell !== ""; }); }).map(function(row) { const item = Object.create(null); headers.forEach(function(header, index) { item[header] = row[index] == null ? "" : row[index]; }); return item; });
      result = JSON.stringify(objects, null, 2);
      filename = "toolbari-data.json";
    } else {
      result = jsonToCsv(parseJsonSafely(input));
      filename = "toolbari-data.csv";
    }
    showCopyableResult(L("রূপান্তরিত ডেটা", "Converted data"), result, filename, L("CSV export-এ spreadsheet formula injection থেকে সুরক্ষা যোগ করা হয়েছে।", "CSV output is guarded against spreadsheet formula injection."));
  });
  if (toolItem.key === "url-codec") return bindSafeClick("runUrlCodec", function() {
    const input = $("#urlCodecInput").value;
    let result;
    try { result = $("#urlCodecMode").value === "encode" ? encodeURIComponent(input) : decodeURIComponent(input); }
    catch { throw new Error(L("সঠিক URL component বা encoded লেখা দিন", "Enter a valid URL component or encoded value")); }
    showCopyableResult(L("URL ফল", "URL result"), result, "toolbari-url.txt");
  });
  if (toolItem.key === "base64-text") return bindSafeClick("runBase64", function() {
    const input = $("#base64Input").value;
    let result;
    try { result = $("#base64Mode").value === "encode" ? utf8ToBase64(input) : base64ToUtf8(input); }
    catch { throw new Error(L("সঠিক Base64 লেখা দিন", "Enter valid Base64 text")); }
    showCopyableResult(L("Base64 ফল", "Base64 result"), result, "toolbari-base64.txt");
  });
  if (toolItem.key === "hash-generator") return bindSafeClick("runHash", async function() {
    const file = $("#hashFile").files[0];
    let data;
    let source;
    if (file) { ensureFileLimit(file, 40); data = await file.arrayBuffer(); source = file.name; }
    else { data = new TextEncoder().encode($("#hashText").value); source = L("লেখা", "Text"); }
    const algorithm = $("#hashAlgorithm").value;
    const result = bytesToHex(await crypto.subtle.digest(algorithm, data));
    showCopyableResult(algorithm + " · " + source, result, "toolbari-" + algorithm.toLowerCase() + ".txt");
  });
  if (toolItem.key === "uuid-generator") return bindSafeClick("runUuid", function() {
    const count = finiteInput("uuidCount");
    if (!Number.isInteger(count) || count < 1 || count > 100) throw new Error(L("১ থেকে ১০০-এর মধ্যে পূর্ণ সংখ্যা দিন", "Choose a whole number from 1 to 100"));
    const result = Array.from({ length: count }, secureUuid).join("\n");
    showCopyableResult("UUID v4", result, "toolbari-uuids.txt");
  });
  if (toolItem.key === "timestamp-converter") {
    const convert = function() {
      const raw = normalizeNumerals($("#timestampValue").value).trim();
      if (!/^-?\d+(?:\.\d+)?$/.test(raw)) throw new Error(L("সঠিক Unix timestamp দিন", "Enter a valid Unix timestamp"));
      const numeric = Number(raw);
      if (!Number.isFinite(numeric)) throw new Error(L("সঠিক Unix timestamp দিন", "Enter a valid Unix timestamp"));
      const unit = $("#timestampUnit").value;
      const date = new Date(unit === "seconds" ? numeric * 1000 : numeric);
      if (Number.isNaN(date.getTime())) throw new Error(L("এই timestamp-এর তারিখ পাওয়া যায়নি", "This timestamp is outside the supported date range"));
      outputSet('<p class="workspace-kicker">' + L("তারিখ ও সময়", "Date and time") + '</p><h3 class="result-title">' + escapeHtml(date.toLocaleString(state.lang === "bn" ? "bn-BD" : undefined, { dateStyle: "full", timeStyle: "long" })) + '</h3><ul class="output-list"><li><span>UTC / ISO</span><strong>' + escapeHtml(date.toISOString()) + '</strong></li><li><span>Unix seconds</span><strong>' + escapeHtml(String(Math.floor(date.getTime() / 1000))) + '</strong></li><li><span>Milliseconds</span><strong>' + escapeHtml(String(date.getTime())) + '</strong></li></ul>');
    };
    bindSafeClick("runTimestamp", convert);
    return bindSafeClick("timestampNow", function() { $("#timestampValue").value = String(Math.floor(Date.now() / 1000)); $("#timestampUnit").value = "seconds"; convert(); });
  }
  if (toolItem.key === "jwt-decoder") return bindSafeClick("runJwt", function() {
    const parts = $("#jwtInput").value.trim().split(".");
    if (parts.length !== 3 || !parts[0] || !parts[1]) throw new Error(L("তিন অংশের একটি JWT দিন", "Enter a JWT with three parts"));
    const decoded = { header: decodeJwtPart(parts[0]), payload: decodeJwtPart(parts[1]) };
    const result = JSON.stringify(decoded, null, 2);
    showCopyableResult(L("শুধু decoded তথ্য", "Decoded data only"), result, "toolbari-jwt-decoded.json", L("Signature যাচাই করা হয়নি—এই ফলকে authentication হিসেবে ব্যবহার করবেন না।", "The signature was not verified—do not treat this result as authentication."));
  });
  if (toolItem.key === "image-resize-crop") {
    const syncResizeControls = function() { $("#resizeBackgroundField").hidden = $("#resizeMode").value !== "contain"; };
    $("#resizeMode").addEventListener("change", syncResizeControls);
    syncResizeControls();
    return bindSafeClick("runResizeCrop", async function() {
      const file = $("#resizeFile").files[0];
      if (!file) throw new Error(L("একটি ছবি বেছে নিন", "Choose an image"));
      ensureFileLimit(file, 20);
      ensureRasterImage(file);
      const width = finiteInput("resizeWidth");
      const height = finiteInput("resizeHeight");
      if (!Number.isInteger(width) || !Number.isInteger(height) || width < 1 || height < 1 || width > 8000 || height > 8000 || width * height > 16000000) throw new Error(L("পূর্ণ pixel-এ সর্বোচ্চ ৮০০০ px এবং ১৬ megapixel ব্যবহার করুন", "Use whole-pixel dimensions up to 8,000 px per side and 16 megapixels"));
      const image = await readImage(file);
      if (image.naturalWidth * image.naturalHeight > 16000000) throw new Error(L("ছবির source ১৬ megapixel-এর নিচে রাখুন", "Use a source image under 16 megapixels"));
      const canvas = createCanvas(width, height);
      const ctx = canvas.getContext("2d");
      ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = "high";
      const mode = $("#resizeMode").value;
      if (mode === "stretch") ctx.drawImage(image, 0, 0, width, height);
      else if (mode === "contain") {
        ctx.fillStyle = $("#resizeBackground").value; ctx.fillRect(0, 0, width, height);
        const scale = Math.min(width / image.width, height / image.height);
        const drawWidth = image.width * scale; const drawHeight = image.height * scale;
        ctx.drawImage(image, (width - drawWidth) / 2, (height - drawHeight) / 2, drawWidth, drawHeight);
      } else {
        const targetRatio = width / height; const sourceRatio = image.width / image.height;
        let sx = 0; let sy = 0; let sw = image.width; let sh = image.height;
        if (sourceRatio > targetRatio) { sw = image.height * targetRatio; sx = (image.width - sw) / 2; }
        else { sh = image.width / targetRatio; sy = (image.height - sh) / 2; }
        ctx.drawImage(image, sx, sy, sw, sh, 0, 0, width, height);
      }
      showCanvasResult(canvas, L("রিসাইজ সম্পন্ন", "Resize complete"), width + " × " + height + " px · " + $("#resizeMode").selectedOptions[0].textContent, "toolbari-" + width + "x" + height + ".png");
    });
  }
  if (toolItem.key === "image-format") {
    $("#formatQuality").addEventListener("input", function() { $("#formatQualityValue").textContent = this.value + "%"; });
    const syncFormatControls = function() {
      const type = $("#formatType").value;
      $("#formatQualityField").hidden = type === "image/png";
      $("#formatBackgroundField").hidden = type !== "image/jpeg";
    };
    $("#formatType").addEventListener("change", syncFormatControls);
    syncFormatControls();
    return bindSafeClick("runImageFormat", async function() {
      const file = $("#formatFile").files[0];
      if (!file) throw new Error(L("একটি ছবি বেছে নিন", "Choose an image"));
      ensureFileLimit(file, 20);
      ensureRasterImage(file);
      const image = await readImage(file);
      if (image.width * image.height > 16000000) throw new Error(L("১৬ megapixel-এর ছোট ছবি ব্যবহার করুন", "Use an image under 16 megapixels"));
      const type = $("#formatType").value;
      const quality = Number($("#formatQuality").value) / 100;
      const canvas = createCanvas(image.width, image.height);
      const ctx = canvas.getContext("2d");
      if (type === "image/jpeg") { ctx.fillStyle = $("#formatBackground").value; ctx.fillRect(0, 0, canvas.width, canvas.height); }
      ctx.drawImage(image, 0, 0);
      const blob = await canvasToBlob(canvas, type, quality);
      if (!blob || blob.type !== type) throw new Error(L("এই ব্রাউজার ফরম্যাটটি তৈরি করতে পারেনি", "This browser could not create the selected format"));
      const extension = type === "image/jpeg" ? "jpg" : type.split("/")[1];
      showCanvasResult(canvas, L("কনভার্ট ও re-encode সম্পন্ন", "Conversion and re-encoding complete"), image.width + " × " + image.height + " px · " + humanBytes(file.size) + " → " + humanBytes(blob.size), "toolbari-clean." + extension, blob);
    });
  }
}

let toastTimer;
function showToast(message) {
  // An open modal dialog covers the page and makes it inert, so tools use the toast inside the dialog.
  const inModal = $("#toolModal").open;
  const toast = inModal ? $("#modalToast") : $("#toast");
  (inModal ? $("#toast") : $("#modalToast")).classList.remove("visible");
  toast.textContent = message;
  toast.classList.add("visible");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(function() { toast.classList.remove("visible"); }, 2700);
}

function calculateQuickAge() {
  const birthValue = $("#birthDate").value;
  const targetValue = $("#targetDate").value;
  if (!birthValue || !targetValue) return showToast(t("invalidDate"));
  const birth = new Date(birthValue + "T12:00:00");
  const target = new Date(targetValue + "T12:00:00");
  if (birth > target) return showToast(t("futureDate"));
  const age = calculateDateParts(birth, target);
  $("#ageResult").innerHTML = '<div class="age-values"><div><strong>' + displayNumber(age.years) + '</strong><span>' + t("years") + '</span></div><div><strong>' + displayNumber(age.months) + '</strong><span>' + t("months") + '</span></div><div><strong>' + displayNumber(age.days) + '</strong><span>' + t("days") + '</span></div></div>';
}

$("#languageSelect").addEventListener("change", function(event) {
  state.lang = event.target.value;
  storeLanguage(state.lang);
  applyTranslations();
  syncAddress(state.activeTool && state.activeTool.key);
});

$("#searchInput").addEventListener("input", function(event) {
  state.query = event.target.value;
  renderTools();
});

$("#categories").addEventListener("click", function(event) {
  const button = event.target.closest("[data-category]");
  if (!button) return;
  state.category = button.dataset.category;
  renderCategories();
  renderTools();
});

$("#toolGrid").addEventListener("click", function(event) {
  const card = event.target.closest("[data-tool]");
  if (card) {
    event.preventDefault();
    openTool(card.dataset.tool);
  }
});

$("#modalClose").addEventListener("click", closeTool);
$("#toolModal").addEventListener("cancel", function(event) { event.preventDefault(); closeTool(); });
$("#toolModal").addEventListener("click", function(event) {
  if (event.target === $("#toolModal")) closeTool();
});
$("#toolWorkspace").addEventListener("click", function(event) {
  const opener = event.target.closest("[data-open-tool]");
  if (opener) openTool(opener.dataset.openTool);
});

$("#calculateAge").addEventListener("click", calculateQuickAge);
$("#navToggle").addEventListener("click", function() {
  const open = $(".site-header").classList.toggle("nav-open");
  this.setAttribute("aria-expanded", String(open));
  updateNavigationLabel();
});
$("#primaryNav").addEventListener("click", function(event) {
  if (event.target.closest("a")) closeNavigation();
});
document.addEventListener("click", function(event) {
  if (!event.target.closest(".site-header")) closeNavigation();
});
document.addEventListener("keydown", function(event) {
  if (event.key === "Escape" && $(".site-header").classList.contains("nav-open")) {
    closeNavigation();
    $("#navToggle").focus();
  }
  if (event.key === "/" && !$("#toolModal").open && !["INPUT","TEXTAREA","SELECT"].includes(document.activeElement && document.activeElement.tagName)) {
    event.preventDefault();
    $("#searchInput").focus();
  }
});

const today = new Date();
const todayString = today.getFullYear() + "-" + String(today.getMonth() + 1).padStart(2, "0") + "-" + String(today.getDate()).padStart(2, "0");
$("#targetDate").value = todayString;
$("#targetDate").max = todayString;
$("#birthDate").max = todayString;
$("#year").textContent = today.getFullYear();
applyTranslations();

const requestedTool = initialParams.get("tool");
if (requestedTool) openTool(requestedTool, { updateAddress: false });
window.addEventListener("popstate", function() {
  const next = new URLSearchParams(window.location.search);
  const nextLang = translations[next.get("lang")] ? next.get("lang") : state.lang;
  if (nextLang !== state.lang) {
    state.lang = nextLang;
    applyTranslations();
  }
  const nextTool = next.get("tool");
  if (nextTool) openTool(nextTool, { updateAddress: false });
  else if (state.activeTool) closeTool({ updateAddress: false });
});

function registerWebMcpTools() {
  const context = document.modelContext;
  if (!context || typeof context.registerTool !== "function") return;
  const lifecycle = new AbortController();
  const safeRegister = function(definition) {
    try {
      Promise.resolve(context.registerTool(definition, { signal: lifecycle.signal })).catch(function() {});
    } catch {}
  };
  safeRegister({
    name: "find_tools",
    title: "Find ToolBari tools",
    description: "Search the visible ToolBari catalog by a Bangla or English phrase and optionally filter by category.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string" },
        category: { type: "string", enum: categories },
        language: { type: "string", enum: ["bn", "en"] }
      },
      required: ["query"],
      additionalProperties: false
    },
    annotations: { readOnlyHint: false, untrustedContentHint: false },
    execute: function(input) {
      if (!input || typeof input.query !== "string") throw new Error("query must be a string");
      if (input.category && !categories.includes(input.category)) throw new Error("unknown category");
      if (input.language) {
        state.lang = input.language;
        localStorage.setItem("toolbari-language", state.lang);
      }
      state.query = input.query;
      state.category = input.category || "all";
      $("#searchInput").value = state.query;
      applyTranslations();
      const queryTokens = canonicalizeSearch(state.query).split(" ").filter(Boolean);
      const matches = tools.filter(function(item) {
        const haystackTokens = normalizedHaystack(item).split(" ").filter(Boolean);
        return (state.category === "all" || item.category === state.category) && queryTokens.every(function(token) {
          return haystackTokens.some(function(haystackToken) { return haystackToken === token || (!canonicalSearchTerms.has(token) && haystackToken.includes(token)); });
        });
      }).slice(0, 20);
      return { count: matches.length, tools: matches.map(function(item) { return { key: item.key, title: state.lang === "bn" ? item.titleBn : item.titleEn, status: item.status }; }) };
    }
  });
  safeRegister({
    name: "calculate_age",
    title: "Calculate age",
    description: "Open the visible Age Calculator and calculate an exact age in years, months and days.",
    inputSchema: {
      type: "object",
      properties: {
        birthDate: { type: "string", pattern: "^\\d{4}-\\d{2}-\\d{2}$" },
        targetDate: { type: "string", pattern: "^\\d{4}-\\d{2}-\\d{2}$" }
      },
      required: ["birthDate", "targetDate"],
      additionalProperties: false
    },
    annotations: { readOnlyHint: false, untrustedContentHint: false },
    execute: function(input) {
      if (!input || !/^\d{4}-\d{2}-\d{2}$/.test(input.birthDate || "") || !/^\d{4}-\d{2}-\d{2}$/.test(input.targetDate || "")) throw new Error("Dates must use YYYY-MM-DD");
      const birth = new Date(input.birthDate + "T12:00:00");
      const target = new Date(input.targetDate + "T12:00:00");
      if (Number.isNaN(birth.getTime()) || Number.isNaN(target.getTime()) || birth > target) throw new Error("Invalid date range");
      const result = calculateDateParts(birth, target);
      openTool("age");
      $("#toolBirth").value = input.birthDate;
      $("#toolTarget").value = input.targetDate;
      $("#runAge").click();
      return result;
    }
  });
}

registerWebMcpTools();
